module barrel_shifter (
    input [7:0] in,
    input [2:0] ctrl,
    output [7:0] out
);

wire [7:0] mux2X1_1, mux2X1_2;

assign mux2X1_1 = (ctrl[0]) ? {in[6:0], 1'b0} : in;
assign mux2X1_2 = (ctrl[1]) ? {in[5:0], 2'b00} : mux2X1_1;

assign out = (ctrl[2]) ? {in[3:0], 4'b0000} : mux2X1_2;

endmodule

module mux2X1( in0,in1,sel,out);
input in0,in1;
input sel;
output out;
assign out=(sel)?in1:in0;
endmodule
